CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_listar_cursos_catalogo`()
BEGIN
  SELECT c.id, im.datos AS emoji_datos, im.clave AS emoji_clave, c.titulo, c.descripcion, c.duracion, c.activo, c.fecha_creacion
  FROM cursos c
